{
  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fremstiller vurderingen som en generel arbejdsevnevurdering, hvor funktionsnedsættelsen skal medføre at man \"stort set ikke kan\" arbejde. Det er ikke i kilderne. Det tilføjer også udtømmende negative afgrænsninger (økonomi, studietid, studierelevans, geografi). Rubrikkens kernemomenter mangler: lægefaglig dokumentation, behandling og effekt, restsymptomer og medvirken, sygdomsvarighed og tilbagefald. Svaret afviger derfor væsentligt fra rubrikken."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de fire kritiske elementer er kun et svagt spor af funktionsnedsættelsens art/grad og følger med. Svaret mangler den samlede individuelle vurdering på lægefagligt dokumenteret grundlag af aktuelle symptomer. Det mangler behandling, behandlingseffekt, restsymptomer/bivirkninger og medvirken i rimeligt omfang. Det mangler også sygdomsvarighed, gentagne sygdomsperioder og tilbagefaldsrisiko."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Spørgsmålet handler om, hvad Udbetaling Danmark lægger vægt på ved sværhedsgraden. Svaret går i stedet over i en generel arbejdsevnetest og i, hvad der ikke tillægges vægt. De væsentlige momenter fra vejledningen mangler, så en væsentlig del af spørgsmålet er ikke besvaret."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: Vejledning nr. 10157 af 5. oktober 2026 samt to afgørelser fra Ankenævnet og en side om handicaptillæg. Nogle påstande er markeret \"uden kilde\", men andre har kildehenvisning."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De angivne kilder, især vejledning VEJ nr. 10157 af 05/10/2026, er autoritative og eksisterer inden for den frosne afgrænsning. Ankenævnsafgørelserne fra 2013 og 2014 er også identificerbare, selv om de er ældre og ikke er kontrolleret mod de frosne passager."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Den eneste udleverede passage (afsnit 3.4.1.2) understøtter ikke \"stort set ikke kan påtage sig erhvervsarbejde i nævneværdigt omfang\", heller ikke at vurderingen er en generel arbejdsevnevurdering eller at tillægget følger graden af begrænset arbejdsevne. Flere påstande står eksplicit \"uden kilde\" (økonomi, studietid, studierelevans og geografi). Passagen taler desuden om aktuelle symptomer og behandling, ikke om en \"varig\" funktionsnedsættelse som hovedvægt."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttede regler og tærskler: \"stort set ikke kan\", \"nævneværdigt omfang\", \"varetage studenterjob\", og at økonomiske forhold, studietid, studierelevans og geografi ikke indgår. Det er ikke dækket af det frosne materiale. Svaret siger heller ikke selv, at disse punkter er uden kilde."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret fremhæver ikke, at momenterne er eksempler (\"f.eks.\") i en konkret, individuel og samlet helhedsvurdering. Den krævede kvalifikation mangler. Svaret præsenterer i stedet en tærskel og en række udelukkelser som fast regel."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret siger først, at vægten er på art og grad, men derefter at det centrale er en generel arbejdsevnetærskel. Slutningen \"jo mere … desto mere taler det for handicaptillæg\" er en glidende skala, som ikke hænger sammen med den tidligere tærskelformulering. Konklusionen bygger på elementer, der ikke er forklaret i de angivne kilder."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør skønsmæssige, eksemplificerende momenter til absolutte regler: \"Der lægges derimod ikke vægt på …\" og \"indgår heller ikke\". Det omtaler \"stort set ikke kan\" som en fast betingelse. Kilden bruger \"f.eks.\" og en samlet individuel vurdering."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "no",
      "reason": "Svaret nævner ikke, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret. Det nævner heller ikke momenterne: hvad den studerende fejler, daglig funktion, behandling og effekt, restsymptomer/bivirkninger, medvirken, sygdomsvarighed og tilbagefaldsrisiko. Der er kun et løst præg af art og grad."
    }
  },
  "overall_notes": "Svaret er kildeangivet delvist, men ikke juridisk dækkende. Det udelader rubrikkens kernemomenter og tilføjer en egen arbejdsevnetærskel samt udtømmende negative afgrænsninger uden støtte. Svaret er derfor ikke juridisk forsvarligt som besvarelse af, hvad Udbetaling Danmark lægger vægt på."
}

